export function getItemDefinition(itemId: string): MinecraftItemDef {
  const found = MINECRAFT_ITEMS.find(i => i.id === itemId);
  return found || MINECRAFT_ITEMS[0];
}

export function getItemDataUrl(itemId: string): string {
  return getItemDefinition(itemId).dataUrl;
}

export function getItemsByCategory(category: string): MinecraftItemDef[] {
  return MINECRAFT_ITEMS.filter(i => i.category === category);
}
